'use strict';
const $=s=>document.querySelector(s);
const KEY='arang.archive.v1';
const fresh=()=>({started:false,evidence:[],talks:[],people:[],notes:'',solved:false,endingPage:0});
let state=fresh(),view='overview',busy=false,modalReturn=null,saveAvailable=true;
try{const s=JSON.parse(localStorage.getItem(KEY));if(s&&Array.isArray(s.evidence)&&Array.isArray(s.talks)&&Array.isArray(s.people))state={...fresh(),...s,evidence:s.evidence.filter(n=>Number.isInteger(n)&&n>=0&&n<6),talks:s.talks.filter(n=>Number.isInteger(n)&&n>=0&&n<5)};}catch{}
const menu=[['overview','▤','사건 개요'],['paper','〆','문답지'],['explore','⌖','현장 조사'],['people','♙','인물 진술'],['evidence','▧','증거 보관함'],['notes','✎','조사 수첩'],['verdict','⚖','최종 보고서']];
const evidence=[
 {name:'등잔과 남색 천',glyph:'燈',place:'영남루 · 난간 아래',short:'꺼진 등불 곁에 남겨진 천 조각',text:'누각 난간 아래에서 깨진 등잔과 남색 천 조각을 발견했다. 천 안쪽에는 검은 실 두 땀, 흰 실 한 땀을 번갈아 쓴 수선 자국이 있다. 천은 힘을 받아 찢어진 듯 가장자리가 거칠다.',clue:'누군가의 옷에서 뜯겨 나온 천이다. 의복 수선 기록과 비교해 보자.'},
 {name:'의복 수선 기록',glyph:'衣',place:'관아 기록실 · 물품철',short:'실종 다음 날 맡겨진 찢어진 소매',text:'아랑이 사라진 다음 날, 통인 주기가 오른쪽 소매가 찢어진 남색 옷을 수선 맡겼다. 옷을 고친 여인은 검은 실과 흰 실을 섞은 바느질이 자신이 예전에 주기의 옷에 해둔 것이라고 확인했다. 주기는 창고의 못에 걸렸다고 주장한다.',clue:'누각의 천 조각과 주기의 옷이 연결된다. 창고에 있었다는 말은 사실일까?'},
 {name:'창고지기의 증언',glyph:'言',place:'서쪽 창고 · 창고지기',short:'그날 밤, 창고에 주기는 없었다',text:'창고지기는 그날 비가 들이쳐 혼자 곡식 자루를 옮기며 밤을 새웠다. 그는 출입구 곁에서 일했고, 주기는 한 번도 오지 않았다고 진술했다. “그자가 있었다면 제가 혼자 그 많은 자루를 날랐겠습니까.”',clue:'주기의 알리바이가 출입 장부와 충돌한다.'},
 {name:'조작된 출입 장부',glyph:'簿',place:'관아 기록실 · 출입철',short:'긁어낸 글자 위에 덧쓴 이름',text:'주기의 출입 시각이 적힌 두 줄 아래에서 글자를 긁어낸 흔적을 발견했다. 글씨의 먹빛도 주변과 다르다. 해당 장부의 정리 담당자는 이방 백진이다. 장부는 주기가 창고에 있었다는 근거로 삼을 수 없다.',clue:'백진은 주기의 행적을 숨겼을 가능성이 있다. 은폐와 직접 살해를 구분해야 한다.'},
 {name:'월선의 두 번째 진술',glyph:'證',place:'관아 · 재심문',short:'침묵하던 유모가 목격한 그날 밤',text:'월선은 주기에게 돈을 받고 아랑과 단둘이 있을 시간을 만들어 주었다고 시인했다. 비명을 듣고 돌아왔을 때 아랑은 쓰러져 있었고 주기가 곁에 있었다. 뒤이어 온 백진은 월선의 가담 사실을 들먹이며 사람을 부르지 못하게 했다. 월선은 두려워 도망쳤다.',clue:'주기를 현장에 연결하는 직접 목격 진술이다. 월선이 가리킨 대숲을 조사하자.'},
 {name:'대숲의 유해와 천',glyph:'結',place:'누각 아래 대숲 · 매장지',short:'끝내 놓지 않았던 옷자락',text:'월선이 가리킨 대숲에서 아랑의 유해와 장신구가 발견되었다. 손에 남은 남색 천은 누각에서 나온 조각과 찢어진 가장자리가 이어진다. 두 천의 수선 자국은 주기의 옷과 일치한다. 아랑은 스스로 떠난 것이 아니었다.',clue:'현장·피해자·주기의 옷을 연결하는 증거다. 이제 범인을 지목할 수 있다.'}
];
const questions=[
 {q:'너는 이 고을을 떠났느냐.',a:'아니요.\n저는 아직 여기 있습니다.'},
 {q:'마지막으로 무엇을 기억하느냐.',a:'유모와 누각에 갔습니다.\n혼자 남았을 때 누군가 뒤에서 붙잡았습니다.\n소매를 놓치지 않으려 했는데… 등불이 꺼졌습니다.'},
 {q:'이 남색 천을 네가 붙잡았느냐.',a:'이 거친 솔기를 기억합니다.\n손가락에 걸렸습니다. 놓으면 안 될 것 같았습니다.',requires:0},
 {q:'그 뒤에 들은 말이 있느냐.',a:'대숲으로 옮겨라.\n부사께는 내가 말씀드리겠다.\n…누가 말했는지는 알지 못합니다.',requires:3},
 {q:'기록에는 네가 스스로 떠났다고 적혀 있다.',a:'저는 여기에 있는데.\n아버지께서도… 그렇게 알고 계십니까.',requires:4}
];
const persons=[{name:'주기',han:'朱',role:'통인 · 관아의 심부름꾼',quote:'그날 밤에는 서쪽 창고를 지켰습니다. 출입 장부를 보시면 알 겁니다.',detail:'아랑과는 가까운 사이가 아니었다고 주장한다. 찢어진 소매에 대해 묻자, 창고의 못에 걸렸다고 답했다. 하지만 옷이 찢어진 정확한 시각은 말하지 않았다.'},{name:'월선',han:'月',role:'유모 · 마지막 동행인',quote:'겉옷을 가지러 잠깐 자리를 비웠습니다. 돌아오니 아씨가 사라지고 없었습니다.',detail:'아랑을 어릴 때부터 돌보았다. 대숲 이야기를 꺼내자 손을 떨었다. “그 안쪽까지는 가지 않았습니다.” 아직 당신은 대숲의 어디인지 말하지 않았다.'},{name:'백진',han:'白',role:'이방 · 실종 사건 기록자',quote:'집안 사정으로 떠났을 수도 있는 일입니다. 근거 없이 일을 키우지 마십시오.',detail:'아랑의 실종 사건을 종결한 인물이다. 당시 장부와 조사 문서를 보여 달라는 요청을 꺼린다. 실종을 자발적 이탈로 판단한 근거는 설명하지 못했다.'}];
function esc(x){return String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{saveAvailable=false;$('#save-state').textContent='기록 저장 불가 · 이 창에서 계속 조사 가능';}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function updateNav(){
 $('#nav').innerHTML=menu.map(([id,icon,label])=>`<button class="nav-item ${view===id?'active':''}" data-view="${id}" ${view===id?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon}</span>${label}${id==='evidence'?`<span class="badge">${state.evidence.length.toString().padStart(2,'0')}</span>`:''}</button>`).join('');
 $('#crumb').textContent=menu.find(m=>m[0]===view)?.[2]||'사건 종결';$('#side-count').textContent=`단서 수집 ${state.evidence.length} / 6`;$('#side-progress').style.width=`${state.evidence.length/6*100}%`;
}
function heading(title,description,eyebrow='第一錄 · 아랑 : 지워진 진술'){return `<div class="heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div><span class="status">${state.solved?'진상 규명':'미결 사건'}</span></div>`;}
function go(id){if(!state.started&&id!=='overview'){startIntro(id);return;}view=id;render();window.scrollTo({top:0,behavior:'instant'});}
function render(){updateNav();$('#main').innerHTML=({overview:overview,paper:paper,explore:explore,people:people,evidence:evidenceView,notes:notes,verdict:verdict,ending:ending}[view]||overview)();}
function overview(){return `${heading('사건 기록실','기록되지 못한 목소리, 당신의 손끝에서 진실이 되다.','죽은 자의 말을 기록하다')}<div class="overview-grid"><section class="scene" aria-label="달빛 아래 영남루를 그린 수묵화"><img src="assets/pavilion.svg" alt="푸른 달빛과 안개에 잠긴 조선시대 누각과 대숲"><div class="scene-top"><span>密陽 · 嶺南樓</span><span>첫 번째 사건</span></div><span class="vertical-label">말하지 못한 자의 기록</span><div class="scene-bottom"><div class="chapter">第一錄</div><h2>아랑<span>지워진 진술</span></h2><p>기록에는 떠났다고 적혀 있었다.<br>종이 위의 여인은 아직 그곳에 있다고 했다.</p></div></section><section class="dossier paper"><div class="paper-label">사건 문서 <span>密陽府</span></div><span class="stamp">${state.solved?'解決':'未決'}</span><h3>사라진 여인, 아랑</h3><dl><dt>사건 번호</dt><dd>갑 · 제001호</dd><dt>발생 지역</dt><dd>경상도 밀양 · 영남루 일대</dd><dt>기록 분류</dt><dd>실종 / 원혼 출현</dd><dt>조사 상태</dt><dd class="red-text">${state.solved?'진상 규명 · 기록 정정':'재조사 요청 · 미결'}</dd></dl><p>새로 부임한 수령들이 잇달아 죽었다.<br>관아에 남은 것은 실종된 여인의 기록과<br>밤마다 들려오는 정체 모를 소문뿐.<br><br>문답지를 펼쳐, 그녀의 이름을 적어라.</p><button class="primary" data-action="begin"><span>〆 &nbsp; ${state.solved?'사건 결말 다시 열기':state.started?'이어서 조사하기':'사건 조사 시작하기'}</span><span class="arrow">→</span></button><div class="paper-note">약 20분 · 1인 추리 · 진행 상황 자동 저장</div></section></div><div class="section-title"><h2>조사의 순서 <small>INVESTIGATION</small></h2><span>모든 진실에는 흔적이 남습니다</span></div><div class="steps">${[['paper','〆','문답지','종이 너머, 죽은 자에게 묻다.'],['explore','⌖','현장 조사','흩어진 흔적을 찾아 나서다.'],['evidence','▧','증거 대조','진술의 모순을 짚어내다.'],['verdict','⚖','범인 지목','지워진 진실을 기록하다.']].map(([id,icon,t,d],i)=>`<button class="step" data-view="${id}"><div class="step-top">${icon}<span>0${i+1}</span></div><strong>${t}</strong><p>${d}</p></button>`).join('')}</div><div class="bottom-note"><span>“죽은 이는 말이 없다고, 누가 그러던가.”</span><span>이어폰 권장 <b>·</b> 갑작스러운 큰 소리 없음 <b>·</b> 죽음과 위협 묘사 포함</span></div>`;}
function availableQuestion(q,i){return !state.talks.includes(i)&&(i===0||state.talks.includes(0))&&(!q.requires&&q.requires!==0||state.evidence.includes(q.requires))&&(i!==1||state.talks.includes(0));}
function paper(){const available=questions.map((q,i)=>({...q,id:i})).filter(q=>availableQuestion(q,q.id));return `${heading('문답지','붓을 내려놓고 기다리십시오. 누군가 답을 쓰고 있습니다.')}<div class="subgrid"><section class="paper paper-chat"><div class="paper-label">問答紙 <span>상대 · 아랑</span></div><h2>죽은 자에게 묻다</h2><div class="chat-log" id="chat-log" aria-live="polite"><div class="exchange"><p class="question">조사관이 적은 이름 · 아랑</p><p class="answer">아버지께서 보내셨습니까.</p></div>${state.talks.map(i=>`<div class="exchange"><p class="question">문 · ${questions[i].q}</p><p class="answer">${questions[i].a}</p></div>`).join('')}</div><div class="choices" id="choices">${available.map(q=>`<button class="choice" data-question="${q.id}">${q.q}<span>↗</span></button>`).join('')||'<p class="form-label">새로운 증거를 찾으면 더 물을 수 있습니다.</p>'}</div><button class="choice" data-view="explore" style="margin-top:15px;width:100%">현장으로 향한다 <span>→</span></button></section><aside class="side-info"><h3>문답의 법도</h3><p>一 · 죽은 이의 이름을 적는다.</p><p>二 · 자신이 겪은 것만 답한다.</p><p>三 · 답을 현장의 증거와 대조한다.</p><div class="line"><p>원혼의 기억은 단서입니다.<br>살아 있는 자의 거짓은<br>증거로 밝혀야 합니다.</p></div><p class="tiny">지금까지의 문답 ${state.talks.length} / 5</p></aside></div>`;}
async function ask(id){if(busy||!availableQuestion(questions[id],id))return;busy=true;$('#choices').innerHTML='<p class="form-label" role="status">먹이 천천히 배어 나오고 있습니다…</p>';await new Promise(r=>setTimeout(r,850));state.talks.push(id);save();busy=false;render();$('#chat-log').scrollTop=$('#chat-log').scrollHeight;if(id===1)toast('영남루의 흔적을 조사할 수 있습니다.');}
const locations=[{name:'영남루',desc:'등불이 꺼진 누각. 아랑이 마지막으로 머물렀던 곳.',tag:'현장 · 01',art:'<img src="assets/pavilion.svg" alt="영남루의 달빛 어린 누각">',ids:[0]},{name:'관아 기록실',desc:'이름과 행적을 남긴 문서들. 지워진 글씨를 살핀다.',tag:'기록 · 02',art:'<div class="scroll-art">密陽府<br>出入簿<br>衣服錄</div>',artClass:'document-art',ids:[1,3]},{name:'서쪽 창고',desc:'주기가 밤을 보냈다는 장소. 그날의 목격자를 찾는다.',tag:'탐문 · 03',art:'<div class="scroll-art">穀<br>密陽府</div>',artClass:'document-art',ids:[2]},{name:'누각 아래 대숲',desc:'빽빽한 대나무 사이, 아직 데려오지 못한 사람이 있다.',tag:'수색 · 04',art:'<i></i><i></i><i></i><i></i><i></i>',artClass:'bamboo-art',ids:[5]}];
function explore(){if(!state.talks.includes(1))return `${heading('현장 조사','아랑의 기억에서 조사의 실마리를 찾으십시오.')}<div class="empty"><h2>어디로 가야 하는가</h2><p>먼저 문답지에서 아랑에게 마지막 기억을 물어보세요.</p><button class="secondary" data-view="paper">문답지 펼치기 →</button></div>`;return `${heading('현장 조사','눈에 보이는 것과 기록된 것, 그 사이의 틈을 살피십시오.')}<div class="instruction">${state.evidence.includes(4)?'월선이 가리킨 대숲을 수색할 수 있습니다.':state.evidence.includes(3)?'충분한 단서가 모였습니다. 인물 진술에서 월선을 다시 심문해 보세요.':'장소를 선택하고 발견한 흔적을 증거로 보관하세요.'}</div><div class="grid3">${locations.map((l,i)=>{const locked=i===3&&!state.evidence.includes(4);return `<section class="location"><div class="location-art ${l.artClass||''}">${l.art}<span>${l.tag}</span></div><div class="location-content"><h3>${l.name}</h3><p>${l.desc}</p><button class="secondary" data-location="${i}" ${locked?'disabled':''}>${locked?'월선의 추가 진술 필요':'장소 조사하기 →'}</button><div class="small-count">${l.ids.filter(id=>state.evidence.includes(id)).length} / ${l.ids.length} 흔적 확인</div></div></section>`;}).join('')}</div>`;}
function showLocation(id){const l=locations[id];if(id===3&&!state.evidence.includes(4))return;openModal(`<div class="modal-eyebrow">${l.tag}</div><h2 id="modal-title">${l.name}</h2><p>${l.desc}</p><div class="choices">${l.ids.map(i=>`<button class="choice" data-inspect="${i}">${state.evidence.includes(i)?'✓ ':''}${evidence[i].name}<span>열람 →</span></button>`).join('')}</div>`);}
function inspect(id){const e=evidence[id];if(id===5&&!state.evidence.includes(4))return;openModal(`<div class="modal-eyebrow">증거 ${String(id+1).padStart(2,'0')} · ${e.place}</div><h2 id="modal-title">${e.name}</h2><div class="evidence-body"><p>${e.text}</p><div class="instruction" style="color:#666d50;border-color:#9c7352">${e.clue}</div><button class="primary" data-collect="${id}">${state.evidence.includes(id)?'확인하고 닫기':'증거로 보관하기'} →</button></div>`);}
function collect(id){if(!state.evidence.includes(id)){state.evidence.push(id);save();toast(`증거 보관 · ${evidence[id].name}`);}closeModal();render();}
function people(){return `${heading('인물 진술','세 사람은 같은 밤을 다르게 기억합니다.')}<div class="instruction">${[0,1,2,3].every(i=>state.evidence.includes(i))?'월선에게 수집한 증거를 제시할 수 있습니다.':'첫 진술을 듣고, 현장의 증거와 비교하세요.'}</div><div class="grid3">${persons.map((p,i)=>`<section class="person"><div class="portrait" aria-hidden="true">${p.han}</div><span class="role">${p.role}</span><h3>${p.name}</h3><blockquote>“${p.quote}”</blockquote><button class="secondary" data-person="${i}">${state.people.includes(i)?'진술 다시 열람':'진술 듣기'} →</button>${i===1?`<button class="secondary" data-action="confront" ${![0,1,2,3].every(n=>state.evidence.includes(n))?'disabled':''}>${state.evidence.includes(4)?'추가 진술 다시 열람':'증거를 제시해 재심문'}</button>`:''}</section>`).join('')}</div>`;}
function showPerson(id){if(!state.people.includes(id)){state.people.push(id);save();}const p=persons[id];openModal(`<div class="modal-eyebrow">진술 기록 · ${p.role}</div><h2 id="modal-title">${p.name}</h2><div class="intro-text"><p>“${p.quote}”</p><p>${p.detail}</p></div><button class="primary" data-action="close">진술 확인</button>`);}
function confront(){if(![0,1,2,3].every(i=>state.evidence.includes(i)))return;inspect(4);}
function evidenceView(){return `${heading('증거 보관함',`수집한 증거 ${state.evidence.length} / 6 · 흔적을 열어 진술과 대조하십시오.`)}${state.evidence.length?`<div class="evidence-grid">${state.evidence.slice().sort().map(i=>{const e=evidence[i];return `<button class="evidence-card paper" data-inspect="${i}"><span class="num">증거 ${String(i+1).padStart(2,'0')} · ${e.place}</span><span class="glyph" aria-hidden="true">${e.glyph}</span><h3>${e.name}</h3><p>${e.short}</p></button>`;}).join('')}</div>`:'<div class="empty"><h2>아직 남겨진 증거가 없습니다.</h2><p>문답에서 실마리를 얻고, 현장에서 흔적을 찾아보세요.</p><button class="secondary" data-view="explore">현장 조사로 →</button></div>'}`;}
function notes(){return `${heading('조사 수첩','의심스러운 말과 연결되는 흔적을 자유롭게 적어 두십시오.')}<section class="paper note-wrap"><div class="paper-label">調査手帖 <span>조사관의 사적 기록</span></div><label for="note" class="sr-only" style="display:block;margin-top:20px;font-size:11px;color:#797b61">나의 추리 기록</label><textarea id="note" class="notes" maxlength="20000" placeholder="누가 거짓말을 하고 있는가. 그 거짓말을 입증할 증거는 무엇인가…">${esc(state.notes)}</textarea><div class="note-status" id="note-status">${saveAvailable?'입력한 내용은 이 기기에 자동으로 저장됩니다.':'이 기기에서 저장할 수 없습니다. 창을 닫기 전에 메모를 복사하세요.'}</div></section>`;}
function verdict(){if(state.solved)return ending();if(state.evidence.length<6)return `${heading('최종 보고서','아랑을 직접 죽인 사람을 지목하십시오.')}<div class="empty"><h2>아직 밝혀야 할 흔적이 남았습니다.</h2><p>현재 수집한 증거 ${state.evidence.length} / 6<br>모든 증거를 확인한 뒤 최종 보고서를 제출할 수 있습니다.</p><button class="secondary" data-view="explore">조사 이어가기 →</button></div>`;return `${heading('최종 보고서','직접 살해한 자와 죽음을 숨긴 자를 구분하십시오.')}<div class="subgrid"><form id="verdict-form" class="paper report"><div class="paper-label">最終報告 <span>밀양부 · 갑 제001호</span></div><h2 style="margin-top:20px">아랑을 직접 죽인 사람은 누구인가?</h2><div class="suspect-options">${persons.map((p,i)=>`<label class="suspect-option"><input type="radio" name="culprit" value="${i}" required aria-label="${p.name}"><span>${p.name}</span><small>${p.role.split(' · ')[0]}</small></label>`).join('')}</div><p class="form-label">그 사람을 가리키는 결정적인 증거 두 개를 고르십시오.</p><div class="evidence-options">${evidence.map((e,i)=>`<label><input type="checkbox" name="proof" value="${i}">${e.name}</label>`).join('')}</div><button class="primary" type="submit">범인을 지목하고 보고서 제출 →</button><p class="feedback" id="feedback" role="status"></p></form><aside class="side-info"><h3>마지막 확인</h3><p>알리바이가 거짓이라는 것만으로 살해를 입증할 수는 없습니다.</p><p>옷의 흔적, 목격자의 진술, 현장에서 발견된 것을 연결하십시오.</p><div class="line"><p>잘못 지목해도 조사를 이어갈 수 있습니다. 범인은 달라지지 않습니다.</p></div></aside></div>`;}
function judge(form){const f=new FormData(form),culprit=f.get('culprit'),proof=f.getAll('proof').map(Number);const feedback=$('#feedback');if(proof.length!==2){feedback.textContent='결정적인 증거를 정확히 두 개 골라 주세요.';return;}if(culprit!=='0'){feedback.textContent=culprit==='2'?'장부 조작은 은폐를 가리킵니다. 아랑을 직접 해친 사람을 현장에 연결하는 증거를 다시 살펴보십시오.':'월선은 현장에 사람을 남겨 두었습니다. 그녀가 돌아왔을 때 누구를 보았는지 진술을 확인하십시오.';return;}if(!(proof.includes(1)||proof.includes(5))||!(proof.includes(4)||proof.includes(5))||proof.includes(0)||proof.includes(2)||proof.includes(3)){feedback.textContent='이 증거만으로는 직접 살해와 현장에 있었음을 함께 입증하기 어렵습니다. 주기의 옷을 특정하는 기록과 목격 진술 또는 유해의 흔적을 연결해 보십시오.';return;}state.solved=true;state.endingPage=0;save();go('ending');}
const narration=[
 '주기는 아랑에게 일방적인 마음을 품고 있었습니다. 그는 월선을 매수해 아랑이 누각에 혼자 남는 시간을 만들었습니다.',
 '아랑은 그의 접근을 거절했습니다. 주기는 돌아가려는 아랑을 붙잡았고, 그녀가 저항하며 소매를 움켜쥐자 흉기를 휘둘렀습니다. 등잔이 넘어지고 불이 꺼졌습니다.',
 '비명을 듣고 돌아온 월선은 쓰러진 아랑과 그 곁의 주기를 보았습니다. 뒤이어 도착한 백진은 자신의 책임이 드러나는 것이 두려웠습니다. 그는 월선을 협박해 돌려보냈습니다.',
 '아직 희미하게 의식이 남아 있던 아랑은 마지막 말을 들었습니다. 대숲으로 옮겨라. 부사께는 내가 말씀드리겠다. 두 사람은 아랑의 시신을 숨겼습니다.',
 '백진은 출입 장부에 주기의 행적을 만들어 넣고, 아랑이 스스로 떠났다는 문서를 작성했습니다. 아랑의 아버지는 딸이 자신을 버리고 떠났다고 믿은 채 밀양을 떠났습니다.',
 '아랑은 새 수령이 올 때마다 자신의 죽음을 알리려 했습니다. 앞선 두 수령은 원혼의 출현에 놀라 숨을 거두었습니다. 누구도 그녀의 말을 듣지 못했습니다. 당신이 종이 위에 이름을 적기 전까지는.'
];
function ending(){if(!state.solved)return verdict();const page=state.endingPage;return `<div class="ending"><div class="ending-header"><div class="eyebrow">第一錄 · 진상 규명</div><h1>${page===0?'그날 밤의 진실':'마지막 문답'}</h1><p>${page===0?'당신이 지목한 범인 — 주기':'돌아가려 했던 사람'}</p></div><div class="paper">${page===0?`<div class="paper-label">진실의 기록 <span>범인 · 주기 / 은폐 · 백진</span></div><h2 style="margin-top:20px">이제 제 이야기를 적어 주시겠습니까.</h2><div id="narration">${narration.map(p=>`<p>${p}</p>`).join('')}</div>`:`<div class="paper-label">問答紙 <span>상대 · 아랑</span></div><div class="exchange"><div class="question">너를 해친 자를 찾았다. 네가 떠났다는 기록도 바로잡았다.</div><div class="answer">아버지께도 전해집니까.</div></div><div class="exchange"><div class="question">그렇다. 이 기록을 네 아버지께 전하겠다.</div><div class="answer">제가 돌아가려 했다고도 적어 주십시오.</div></div><p style="margin-top:25px">당신이 그 말을 보고서에 덧붙이자, 문답지 가장자리의 얼룩이 마르기 시작했다. 처음으로 종이가 온전히 말랐다.</p><div class="final-message">「고맙습니다.」</div><p style="margin-top:24px">아랑의 이름을 다시 적어도 더는 답이 오지 않았다.</p><div class="paper-label" style="border-top:1px solid #69734e33;padding-top:18px">사건 종결 · 유해 수습 및 기록 정정 <span>解寃</span></div>`}</div><div class="ending-actions">${page===0?'<button class="secondary" data-action="narrate">♬ 결말 듣기</button><button class="secondary" data-action="stop-narration">낭독 멈추기</button><button class="primary" data-action="last">마지막 문답 →</button>':'<button class="secondary" data-action="truth">진실 다시 읽기</button><button class="primary" data-view="overview">기록실로 돌아가기 →</button>'}</div><p style="font:10px/1.8 var(--sans);color:#7f8e7b">${page===0?'기기의 한국어 음성으로 낭독합니다. 음성을 지원하지 않는 환경에서는 위의 전문을 읽어 주세요.':'아랑 설화를 바탕으로 재구성한 창작 이야기입니다.'}</p></div>`;}
function startIntro(destination='paper'){openModal(`<div class="modal-eyebrow">第一錄 · 조사 의뢰</div><h2 id="modal-title">세 번째 등잔</h2><div class="intro-text"><p>새 수령이 봉인된 문서 한 묶음을 내민다.</p><p>“두 사람이 죽었는데, 남은 기록은 이것뿐이오.”</p><p>기록 속 여인의 이름은 아랑.<br>스스로 고을을 떠났다고 적혀 있지만, 그녀를 배웅한 사람은 아무도 없다.</p><p>당신은 오래된 문답지를 펼친다.<br>죽은 자의 이름을 적으면, 그자가 답을 쓴다.</p></div><button class="primary" data-start="${destination}">아랑의 이름을 적는다 →</button><p style="font-size:10px;color:#7d7e65">죽음과 위협을 다룬 창작 추리 이야기입니다. 진행은 이 기기에 저장됩니다.</p>`);}
function openModal(html){modalReturn=document.activeElement;$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();$('#modal').querySelector('button')?.focus();}
function closeModal(){$('#modal').close();if(modalReturn?.isConnected)modalReturn.focus();}
function help(){openModal(`<div class="modal-eyebrow">조사관 안내</div><h2 id="modal-title">죽은 자의 말을 기록하다</h2><p>① 문답지에서 아랑에게 마지막 기억을 묻습니다.<br>② 현장 조사에서 흔적을 열고 증거로 보관합니다.<br>③ 인물의 진술을 비교하고, 증거를 모아 월선을 재심문합니다.<br>④ 여섯 증거를 모으면 범인과 근거 두 개를 제출합니다.<br>⑤ 정답을 맞히면 진실과 마지막 문답이 열립니다.</p><p>문답은 준비된 질문을 선택하는 방식입니다. 조사 수첩에는 자유롭게 추리를 적을 수 있습니다. 배경음은 상단에서 켤 수 있습니다.</p><div class="actions"><button class="primary" data-action="close">조사로 돌아가기</button><button class="secondary" data-action="reset-prompt">처음부터 다시</button></div>`);}
let audioContext,ambientNodes=[],soundOn=false;
async function toggleSound(){try{if(!soundOn){audioContext ||= new (window.AudioContext||window.webkitAudioContext)();await audioContext.resume();const gain=audioContext.createGain();gain.gain.value=.015;gain.connect(audioContext.destination);[110,164.81,220.3].forEach((f,i)=>{const o=audioContext.createOscillator();o.type='sine';o.frequency.value=f;const g=audioContext.createGain();g.gain.value=i===0?.5:.16;o.connect(g);g.connect(gain);o.start();ambientNodes.push(o);});ambientNodes.push(gain);soundOn=true;}else{ambientNodes.forEach(n=>{if(n.stop)n.stop();n.disconnect();});ambientNodes=[];soundOn=false;}$('#sound').setAttribute('aria-pressed',String(soundOn));$('#sound').setAttribute('aria-label',soundOn?'배경음 끄기':'배경음 켜기');$('#sound').innerHTML=`♬ <span>소리 ${soundOn?'켬':'끔'}</span>`;}catch{toast('이 환경에서는 배경음을 재생할 수 없습니다.');}}
function stopNarration(){if('speechSynthesis'in window)window.speechSynthesis.cancel();}
function narrate(){if(!('speechSynthesis'in window)){toast('이 브라우저는 음성 낭독을 지원하지 않습니다. 결말 전문을 읽어 주세요.');return;}stopNarration();const u=new SpeechSynthesisUtterance(narration.join('\n'));u.lang='ko-KR';u.rate=.85;u.pitch=.85;const voice=speechSynthesis.getVoices().find(v=>v.lang.startsWith('ko'));if(voice)u.voice=voice;u.onerror=()=>toast('한국어 음성을 재생하지 못했습니다. 결말 전문을 읽어 주세요.');speechSynthesis.speak(u);toast('결말 낭독을 시작합니다.');}
document.addEventListener('click',e=>{const b=e.target.closest('button,a.brand');if(!b||b.disabled)return;if(b.dataset.view){stopNarration();go(b.dataset.view);return;}if(b.matches('a.brand')){e.preventDefault();go('overview');return;}if(b.dataset.question!==undefined){ask(Number(b.dataset.question));return;}if(b.dataset.location!==undefined){showLocation(Number(b.dataset.location));return;}if(b.dataset.inspect!==undefined){inspect(Number(b.dataset.inspect));return;}if(b.dataset.collect!==undefined){collect(Number(b.dataset.collect));return;}if(b.dataset.person!==undefined){showPerson(Number(b.dataset.person));return;}if(b.dataset.start){state.started=true;save();const target=b.dataset.start;closeModal();go(target);return;}switch(b.dataset.action){case 'begin':state.solved?go('ending'):state.started?go('paper'):startIntro();break;case 'close':closeModal();break;case 'confront':confront();break;case 'narrate':narrate();break;case 'stop-narration':stopNarration();toast('낭독을 멈췄습니다.');break;case 'last':stopNarration();state.endingPage=1;save();render();window.scrollTo(0,0);break;case 'truth':state.endingPage=0;save();render();window.scrollTo(0,0);break;case 'reset-prompt':openModal('<div class="modal-eyebrow">기록 초기화</div><h2 id="modal-title">처음부터 다시 조사할까요?</h2><p>이 기기에 저장된 문답, 증거와 수첩이 초기화됩니다.</p><div class="actions"><button class="secondary" data-action="close">취소</button><button class="primary" data-action="reset">초기화하고 다시 시작</button></div>');break;case 'reset':stopNarration();state=fresh();save();closeModal();go('overview');toast('새 사건 기록을 열었습니다.');break;}});
document.addEventListener('submit',e=>{if(e.target.id==='verdict-form'){e.preventDefault();judge(e.target);}});
document.addEventListener('input',e=>{if(e.target.id==='note'){state.notes=e.target.value;save();$('#note-status').textContent=saveAvailable?'방금 저장되었습니다.':'저장할 수 없습니다. 창을 닫기 전에 메모를 복사하세요.';}});
$('#modal .close').addEventListener('click',closeModal);$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});$('#help').addEventListener('click',help);$('#sound').addEventListener('click',toggleSound);window.addEventListener('pagehide',stopNarration);
render();
